#include <iostream>
#include <vector>
using namespace std;

int main() {
    vector<int> a = {5, 1, 4, 2};
    int n = a.size();
    for (int i = 0; i < n - 1; i++)          // n − 1 проходов
        for (int j = 0; j < n - 1 - i; j++)  // хвост уже отсортирован
            if (a[j] > a[j + 1])             // соседи стоят неправильно —
                swap(a[j], a[j + 1]);        // меняем местами
    for (int x : a) cout << x << " ";
    cout << endl;                            // 1 2 4 5
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    vector<int> a = {2, 5, 8, 12, 16, 23, 38};  // массив отсортирован!
    int x = 23, lo = 0, hi = a.size() - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;     // середина отрезка
        if (a[mid] == x) { cout << "index " << mid << endl; break; }
        if (a[mid] < x) lo = mid + 1;  // ищем в правой половине
        else hi = mid - 1;             // ищем в левой половине
    }
    return 0;
}

