#include <iostream>
#include <string>
using namespace std;

class Student {
private:
    string name;  // скрытые данные — инкапсуляция
    int score;
public:
    Student(string n, int s) : name(n), score(s) {}  // конструктор
    void addPoints(int p) { score += p; }            // метод меняет поле
    void print() { cout << name << ": " << score << endl; }
};

int main() {
    Student a("Aruzhan", 80);  // создаём объект
    a.addPoints(15);
    a.print();                 // Aruzhan: 95
    return 0;
}

#include <iostream>
using namespace std;

struct Shape {
    virtual double area() { return 0; }  // virtual — можно переопределить
};
struct Rect : Shape {                    // Rect наследует Shape
    double w, h;
    Rect(double w, double h) : w(w), h(h) {}
    double area() override { return w * h; }
};

int main() {
    Rect r(3, 4);
    Shape &s = r;               // ссылка на родителя
    cout << s.area() << endl;   // вызывается версия Rect: 12
    return 0;
}

